import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/00-%E5%BC%80%E7%AF%87%E8%AF%8D%EF%BD%9C%E6%99%AE%E9%80%9A%E5%BC%80%E5%8F%91%E8%80%85%E9%81%87%E4%B8%8AAI%E6%97%B6%E4%BB%A3%EF%BC%8C%E5%A6%82%E4%BD%95%E7%A0%B4%E5%B1%80%EF%BC%9F.html","title":"开篇词｜普通开发者遇上AI时代，如何破局？","lang":"zh-CN","frontmatter":{"title":"开篇词｜普通开发者遇上AI时代，如何破局？","date":"2025-02-10T14:55:01.000Z","icon":"rengongzhineng","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"footer":"长期招收编程一对一学员！微信：Jiabcdefh, <a href=\\"https://beian.miit.gov.cn/\\" target=\\"_blank\\">闽ICP备19021486号-6</a>","description":"你好，我是悦创。 说起来，我和 AI 还挺有缘分的。由于运营了一个几万人的数据类技术社群，我大概 5 年前就考虑用 AI 自动写自媒体文章替代人工，这个时间比 2023 年 GPT 大模型爆发早多了。 我们从投资的角度看，AI 革命的确是一场盛宴，那些大的餐桌上早就坐满了各种人。但问题在于，属于我们普通开发者的位置在哪呢？ 从 2023 到 2024 ...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"开篇词｜普通开发者遇上AI时代，如何破局？\\",\\"image\\":[\\"https://bornforthis.cn/gzh.jpg\\",\\"https://bornforthis.cn/zsxq.jpg\\"],\\"datePublished\\":\\"2025-02-10T14:55:01.000Z\\",\\"dateModified\\":\\"2025-04-10T23:49:50.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"AI悦创\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/column/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/00-%E5%BC%80%E7%AF%87%E8%AF%8D%EF%BD%9C%E6%99%AE%E9%80%9A%E5%BC%80%E5%8F%91%E8%80%85%E9%81%87%E4%B8%8AAI%E6%97%B6%E4%BB%A3%EF%BC%8C%E5%A6%82%E4%BD%95%E7%A0%B4%E5%B1%80%EF%BC%9F.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"开篇词｜普通开发者遇上AI时代，如何破局？"}],["meta",{"property":"og:description","content":"你好，我是悦创。 说起来，我和 AI 还挺有缘分的。由于运营了一个几万人的数据类技术社群，我大概 5 年前就考虑用 AI 自动写自媒体文章替代人工，这个时间比 2023 年 GPT 大模型爆发早多了。 我们从投资的角度看，AI 革命的确是一场盛宴，那些大的餐桌上早就坐满了各种人。但问题在于，属于我们普通开发者的位置在哪呢？ 从 2023 到 2024 ..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://bornforthis.cn/gzh.jpg"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-04-10T23:49:50.000Z"}],["meta",{"property":"article:author","content":"AI悦创"}],["meta",{"property":"article:published_time","content":"2025-02-10T14:55:01.000Z"}],["meta",{"property":"article:modified_time","content":"2025-04-10T23:49:50.000Z"}]]},"git":{"createdTime":1739170838000,"updatedTime":1744328990000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"bornforthis@bornforthis.cn","commits":11,"url":"https://github.com/AndersonHJB"}],"changelog":[{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"3aa2ec627d0f1d171373220ef46cd78c1011e963","time":1739181156000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新AI大模型项目落地实战文档，修正开篇词链接并新增第一章内容，提升文档结构和可读性"},{"hash":"d885dff75b03cb0f65665faac1805878d7516ac2","time":1739179753000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新AI大模型项目落地实战文档，优化第二步内容，增强行业适配性和实用性"},{"hash":"49c0619fd2964559170eef9a8f7119599526ec1e","time":1739179476000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新AI大模型项目落地实战文档，修正路径格式并替换多张图片，提升内容一致性和视觉效果"},{"hash":"b678f74778c3bbeb1d36ba3007c630df9a5f83ee","time":1739179178000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新AI大模型项目落地实战文档，添加开篇词及相关链接，提升内容结构和可读性"},{"hash":"ac4195a859359f970f153f96c9d770b9bf5d64ac","time":1739178861000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新AI大模型项目落地实战文档，增加课程宣传语及对工程师、技术管理者和创业者的价值阐述，提升内容深度和实用性"},{"hash":"a35a7524c204be1eaf1bc3cd1a0e3b15fd5ca6ec","time":1739172024000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新AI课程文档，替换图片以提升内容的视觉效果和相关性"},{"hash":"3cd9e9cfd15c27cd021ef5754591dfc6c721da36","time":1739171461000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新AI课程文档，增加营销AI创业项目和电商行业大模型微调项目的详细介绍，提升内容深度和实用性"},{"hash":"09c59e5a752e293d16cd15347a2a3f13cd3651b6","time":1739171378000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新AI项目开篇词文档，增强内容可读性并补充实战案例，阐述AI开发与传统开发的区别"},{"hash":"3f7160cc7695874b549d8ae5d9b67e6fae431efe","time":1739170838000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"添加AI大模型项目落地实战开篇词文档，分享普通开发者在AI时代的应对策略"}]},"readingTime":{"minutes":19.15,"words":5744},"filePathRelative":"column/AI大模型项目落地实战/00-开篇词｜普通开发者遇上AI时代，如何破局？.md","excerpt":"<figure><figcaption></figcaption></figure>\\n<p>你好，我是悦创。</p>\\n<p>说起来，我和 AI 还挺有缘分的。由于运营了一个几万人的数据类技术社群，我大概 5 年前就考虑用 AI 自动写自媒体文章替代人工，这个时间比 2023 年 GPT 大模型爆发早多了。</p>\\n<p>我们从投资的角度看，AI 革命的确是一场盛宴，那些大的餐桌上早就坐满了各种人。但问题在于，<strong>属于我们普通开发者的位置在哪呢？</strong></p>\\n<p>从 2023 到 2024 年，机缘巧合之下，我参与了多个大模型相关的落地项目开发和运营，有应用开发、微调开发，甚至专有模型开发。带着这些项目的经验，我想给你分享一些普通开发者的道路。</p>","autoDesc":true}`),a={name:`00-开篇词｜普通开发者遇上AI时代，如何破局？.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<figure><img src="/assets/6114e9249796d8070b5ce5f11273b8ea-C4vNoxhm.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>你好，我是悦创。</p><p>说起来，我和 AI 还挺有缘分的。由于运营了一个几万人的数据类技术社群，我大概 5 年前就考虑用 AI 自动写自媒体文章替代人工，这个时间比 2023 年 GPT 大模型爆发早多了。</p><p>我们从投资的角度看，AI 革命的确是一场盛宴，那些大的餐桌上早就坐满了各种人。但问题在于，<strong>属于我们普通开发者的位置在哪呢？</strong></p><p>从 2023 到 2024 年，机缘巧合之下，我参与了多个大模型相关的落地项目开发和运营，有应用开发、微调开发，甚至专有模型开发。带着这些项目的经验，我想给你分享一些普通开发者的道路。</p><h2 id="_1-开发者的-ai-之路怎么走" tabindex="-1"><a class="header-anchor" href="#_1-开发者的-ai-之路怎么走"><span>1. 开发者的 AI 之路怎么走？</span></a></h2><p>从新技术的发展来看，去年投入这个领域的肯定只是 10% 的先行者，现在开始投入的是 60% 的理性参与者。我想，打开这门课的你肯定也是其中一员。我们技术人更加务实，大家更关心自己现有的项目，绞尽脑汁地想着业务如何跟 AI 结合。这个到底上哪一个餐桌的问题，还没有确切的答案。</p><figure><img src="/assets/60d59afde9dea5b570f00b26ce429e0f-DTDsiOkV.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>想要走出普通开发者的 AI 之路，我们首先要意识到“<strong>两个区别</strong>”。</p><p>从工程师的角度看，我们考虑的是实实在在的技术价值。那么<strong>大模型 AI 技术和传统技术价值在哪呢？</strong> 传统的信息技术相当于把人类知识信息化，解决的是信息的物理传递问题，仅仅是一个工具而已。但实际上是人还是一个生产者。现在，AI 也加入了生产者角色当中。</p><p>比如下面的女装产品在线客服。这个生产者就相当于是加入了一个新的角色，它也能来创造，而且在信息的流转和处理上甚至是自动的。这就是我们常说的“效率百倍提升”，也是 AI 技术最直观的价值。</p><figure><img src="/assets/04a5665f6yyf0c5d779867b851681cfa-kqRb5gdO.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>那回到开发者身上，AI 开发和传统开发有什么不同呢？</p><p>我们这里说的 AI 开发是基于大模型的开发。大模型作为一个全新的物种，类比传统开发的话，就是一个全能数据库。这个数据库不仅有全人类的知识，还有全人类的算法。你可以把它理解为和传统开发相比“基础设施”的不同，起点高一些。</p><p>另一方面，以前传统数据库读写数据要用 SQL 等编程语言，但现在从大模型生成数据，只要用自然语言就可以了。自然语言的交互方式其实是颠覆性的，再加上 Agent 智能体这类低代码开发平台的出现，实际上人人都可以开发 AI 应用。</p><p><strong>那原来开发工程师的位置在哪里呢？</strong> 一定要理解，AI 和我们并不是替代的关系，而是融合。</p><p>传统开发的最重要的事情就是要理解客户的需求，把需求翻译成计算机系统的流程和逻辑。所以，<strong>我们要在 AI 时代从翻译业务逻辑的程序员转变为能调教大模型的工程师。</strong></p><p>第一步，<strong>学会低成本跟大模型打配合</strong>。举个简单的例子，我们要用 AI 写一篇文章，正确的方法不是直接让他写一篇文章，而是你把文章架构思考清楚后让大模型写具体细节。这样配合下来整体成本最低，并且能发挥大模型优势。</p><p>第二步，<strong>掌握大模型微调和专有模型开发能力，为其他人创造行业智能体</strong>。这需要从日常搜索开始，直到用 AI 完成一个创新项目为止，逐步获得调教大模型的能力。（其实也就是，一个 AI 大模型要真正的适配某个行业，那最好的方式就是跟随这个行业从 0 开始，到这个行业成熟）</p><p>就在我写这篇文章的当下，关于“技术采纳生命周期”曲线这个概念死活想不起来，搜索完全解决不了，但是 AI 解决起来就很轻松。</p><figure><img src="/assets/d52a0367621cc986151ea5a0668ff4yy-DZZAlCkA.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>落地方向明白了，但现在的问题在于，市面上大部分微调相关的资料，概念太多了，实际项目、真实过程、工程经验太少了。这也正是我将课程重点放在“实战案例”的原因。</p><h2 id="课程设计-实战经验笔记" tabindex="-1"><a class="header-anchor" href="#课程设计-实战经验笔记"><span>课程设计：实战经验笔记</span></a></h2><p>不夸张地说，我们课程是从百万级投入所得到的经验和教训总结。</p><p>这门课具体怎么展开呢？我准备了应用开发、微调开发、专有模型开发三大层次的四个案例。案例的技术难度也是逐步深入的，有助于你逐级提高大模型开发能力。而且每个章节都有对应的彩蛋。</p><figure><img src="/assets/8c4a403f64ac7aae8c078ab5792efffd-20250210151621550-C7ul5toh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><strong>课程第一部分，我们一起战胜“大模型算法恐惧症”。</strong> 我会用两节课分别说说大模型的基本原理和 ChatGPT 的工程创新，你也不用担心原理讲得不多、理解不透，这两节绝对是精华中的精华。比如下面我总结出的 Transformer 详细的程序流程图，理解了它，就已经事半功倍了。最后你会了解到，成百上千的大模型背后原理是如此简单。之后的全部内容就都是工程实战了。</p><figure><img src="/assets/111-bNDFsejv.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><strong>课程第二部分，是一个教育领域大模型应用开发实战案例。</strong> 具体来说，就是帮老师做一个 C 语言的判题系统，让判作业这件事提升 10-20 倍的效率。这是我去年接触到的最落地的实战项目，麻雀虽小，五脏俱全。如果你想了解 AI 业务价值具体怎么落地，学习提示词技术在项目中的实战经验，也想将 AI 应用和传统应用开发相结合，那它真的非常适合你。</p><figure><img src="/assets/image-20250210151853534-7q0dSvpJ.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><strong>课程第三部分，是一个完整的营销 AI 创业项目全过程开发。</strong> 这个项目经历了一年多的打磨，总开发投入在百万级别，包含营销视频、营销图片、营销文章等等的制作。换成咱们技术人的话，就是涵盖了多模态大模型、业务分析与应用开发、Agent 智能体以及平台开发、大模型和小模型结合等方面，对你来说一定是一个质的提升。</p><p>我还会在复盘当中加入部分商业思考，对你判断自己手头的项目是否靠谱非常有帮助。</p><p><strong>课程第四、第五部分，分别是电商行业大模型微调项目以及一个专家模型开发项目。</strong> 把它们放在一起说，是因为这里的技术难度会陡然增加。基于开源大模型的微调和二次开发实际上是除了大模型算法之外，在应用层最高难度的技术了。特别是专家模型项目，里面应用到的大模型技术在开发中把效率提升到了极致，非常适合技术极客学习。</p><p>不必担心技术难度引起学习困难，我还是会站在应用开发的角度来分析和总结，比如下面就是一张调参流程的图片，很清晰，你可以先猜猜这个项目里具体发生了什么。</p><figure><img src="/assets/33-BIiKxLNb.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="训练大脑里的大模型" tabindex="-1"><a class="header-anchor" href="#训练大脑里的大模型"><span>训练大脑里的大模型</span></a></h2><p>“大模型到底是什么新物种！一个 7 年老程序员，躬身入局 AI 时代，一年实战经验小记。”</p><p>对于工程师或超级个体来说，这门课可以帮助你完成从大模型知识到能力的跃迁，提高竞争力。</p><p>对于技术管理者来说，课程有大量丰富的架构，项目设计和经验教训总结，能帮你减少大模型项目实战中走弯路的概率。对于创业创新者来说，我们在多个行业的业务实践，已经取得了客户价值，对你的 AI 业务创新也很有参考价值。</p><p>很多人一说起大模型，想到的是“从 0 开始训练一个自己的大模型”，但我的经验表明，<strong>人脑子里的大模型才是真正的关键。</strong></p><p><strong>就像大模型微调的本质是调整大模型参数的数值，并不是更新具体的数据。</strong> 如果把大模型生成式比作一个“人”走路的话，参数更新就是在调整地图上的路径，目的是让这个“人”走的路“方向正确”，也就是调整你想让他输出的预期方向。</p><p>训练我们大脑里的大模型，就是要不断地将 AI 大模型和实际工作结合，用这些经验调教你的大脑，让它具备驾驭 AI 大模型的思维。我们需要的不只是更新知识，而是大模型开发的思维和方法。</p><p>希望你通过这些大模型应用开发案例的学习，能够尽快将 AI 结合到你自己的应用里，实现百倍的价值提升！</p><p>咱们这门课的案例，有教师的判作业系统，有营销文章 / 营销图片 / 营销视频这类 AI 营销系统的开发，还有电商行业微调达大模型，还有大模型评估专家的开发。你期待哪个项目？你手上在做什么项目？关于开发者的大模型之路，你还有什么疑问吗？</p><p>欢迎你在留言区和我交流，咱们下一讲，正式迈出第一步！</p><p>欢迎关注我公众号：AI悦创，有更多更好玩的等你发现！</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发」，全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><details class="hint-container details"><summary>.</summary><p>不知道你有没有听过一个名词叫“上古程序员”？我就是这样一名程序员，近 20 年的互联网开发经历当中，一直在数据开发、云计算、大数据、应用开发等偏后端开发的方向深耕。早期在新浪网做到技术专家级别，2010 年之后以技术合伙人的身份参与了多个创业项目，参与的创业项目曾经做到 3000 人规模。2023 年初处在持续创业状态。</p><p>说起来，我和 AI 还挺有缘分的。由于运营了一个几万人的数据类技术社群，我大概 5 年前就考虑用 AI 自动写自媒体文章替代人工，这个时间比 2023 年 GPT 大模型爆发早多了。</p><p>我们从投资的角度看，AI 革命的确是一场盛宴，那些大的餐桌上早就坐满了各种人。但问题在于，<strong>属于我们普通开发者的位置在哪呢？</strong></p><p>从 2023 到 2024 年，机缘巧合之下，我参与了多个大模型相关的落地项目开发和运营，有应用开发、微调开发，甚至专有模型开发。带着这些项目的经验，我想给你分享一些普通开发者的道路。</p><h2 id="开发者的-ai-之路怎么走" tabindex="-1"><a class="header-anchor" href="#开发者的-ai-之路怎么走"><span>开发者的 AI 之路怎么走？</span></a></h2><p>从新技术的发展来看，去年投入这个领域的肯定只是 10% 的先行者，现在开始投入的是 60% 的理性参与者。我想，打开这门课的你肯定也是其中一员。我们技术人更加务实，大家更关心自己现有的项目，绞尽脑汁地想着业务如何跟 AI 结合。这个到底上哪一个餐桌的问题，还没有确切的答案。</p><figure><img src="/assets/60d59afde9dea5b570f00b26ce429e0f-DTDsiOkV.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>想要走出普通开发者的 AI 之路，我们首先要意识到“两个区别”。</p><p>从工程师的角度看，我们考虑的是实实在在的技术价值。那么<strong>大模型 AI 技术和传统技术价值在哪呢？</strong> 传统的信息技术相当于把人类知识信息化，解决的是信息的物理传递问题，仅仅是一个工具而已。但实际上是人还是一个生产者。现在，AI 也加入了生产者角色当中。</p><p>比如下面的女装产品在线客服。这个生产者就相当于是加入了一个新的角色，它也能来创造，而且在信息的流转和处理上甚至是自动的。这就是我们常说的“效率百倍提升”，也是 AI 技术最直观的价值。</p><figure><img src="/assets/04a5665f6yyf0c5d779867b851681cfa-kqRb5gdO.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>那回到开发者身上，AI 开发和传统开发有什么不同呢？</p><p>我们这里说的 AI 开发是基于大模型的开发。大模型作为一个全新的物种，类比传统开发的话，就是一个全能数据库。这个数据库不仅有全人类的知识，还有全人类的算法。你可以把它理解为和传统开发相比“基础设施”的不同，起点高一些。</p><p>另一方面，以前传统数据库读写数据要用 SQL 等编程语言，但现在从大模型生成数据，只要用自然语言就可以了。自然语言的交互方式其实是颠覆性的，再加上 Agent 智能体这类低代码开发平台的出现，实际上人人都可以开发 AI 应用。</p><p><strong>那原来开发工程师的位置在哪里呢？</strong> 一定要理解，AI 和我们并不是替代的关系，而是融合。</p><p>传统开发的最重要的事情就是要理解客户的需求，把需求翻译成计算机系统的流程和逻辑。所以，<strong>我们要在 AI 时代从翻译业务逻辑的程序员转变为能调教大模型的工程师。</strong></p><p>第一步，<strong>学会低成本跟大模型打配合</strong>。举个简单的例子，我们要用 AI 写一篇文章，正确的方法不是直接让他写一篇文章，而是你把文章架构思考清楚后让大模型写具体细节。这样配合下来整体成本最低，并且能发挥大模型优势。</p><p>第二步，<strong>掌握大模型微调和专有模型开发能力，为其他人创造行业智能体</strong>。这需要从日常搜索开始，直到用 AI 完成一个创新项目为止，逐步获得调教大模型的能力。</p><p>就在我写这篇文章的当下，关于“技术采纳生命周期”曲线这个概念死活想不起来，搜索完全解决不了，但是 AI 解决起来就很轻松。</p><figure><img src="/assets/d52a0367621cc986151ea5a0668ff4yy-DZZAlCkA.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>落地方向明白了，但现在的问题在于，市面上大部分微调相关的资料，概念太多了，实际项目、真实过程、工程经验太少了。这也正是我将课程重点放在“实战案例”的原因。</p><h2 id="课程设计-实战经验笔记-1" tabindex="-1"><a class="header-anchor" href="#课程设计-实战经验笔记-1"><span>课程设计：实战经验笔记</span></a></h2><p>不夸张地说，我们课程是从百万级投入所得到的经验和教训总结。</p><p>这门课具体怎么展开呢？我准备了应用开发、微调开发、专有模型开发三大层次的四个案例。案例的技术难度也是逐步深入的，有助于你逐级提高大模型开发能力。而且每个章节都有对应的彩蛋。</p><figure><img src="/assets/8c4a403f64ac7aae8c078ab5792efffd-20250210151621550-C7ul5toh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><strong>课程第一部分，我们一起战胜“大模型算法恐惧症”。</strong> 我会用两节课分别说说大模型的基本原理和 ChatGPT 的工程创新，你也不用担心原理讲得不多、理解不透，这两节绝对是精华中的精华。比如下面我总结出的 Transformer 详细的程序流程图，理解了它，就已经事半功倍了。最后你会了解到，成百上千的大模型背后原理是如此简单。之后的全部内容就都是工程实战了。</p><figure><img src="/assets/111-bNDFsejv.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><strong>课程第二部分，是一个教育领域大模型应用开发实战案例。</strong> 具体来说，就是帮老师做一个 C 语言的判题系统，让判作业这件事提升 10-20 倍的效率。这是我去年接触到的最落地的实战项目，麻雀虽小，五脏俱全。如果你想了解 AI 业务价值具体怎么落地，学习提示词技术在项目中的实战经验，也想将 AI 应用和传统应用开发相结合，那它真的非常适合你。</p><figure><img src="/assets/image-20250210151853534-7q0dSvpJ.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><strong>课程第三部分，是一个完整的营销 AI 创业项目全过程开发。</strong> 这个项目经历了一年多的打磨，总开发投入在百万级别，包含营销视频、营销图片、营销文章等等的制作。换成咱们技术人的话，就是涵盖了多模态大模型、业务分析与应用开发、Agent 智能体以及平台开发、大模型和小模型结合等方面，对你来说一定是一个质的提升。</p><p>我还会在复盘当中加入部分商业思考，对你判断自己手头的项目是否靠谱非常有帮助。</p><p><strong>课程第四、第五部分，分别是电商行业大模型微调项目以及一个专家模型开发项目。</strong> 把它们放在一起说，是因为这里的技术难度会陡然增加。基于开源大模型的微调和二次开发实际上是除了大模型算法之外，在应用层最高难度的技术了。特别是专家模型项目，里面应用到的大模型技术在开发中把效率提升到了极致，非常适合技术极客学习。</p><p>不必担心技术难度引起学习困难，我还是会站在应用开发的角度来分析和总结，比如下面就是一张调参流程的图片，很清晰，你可以先猜猜这个项目里具体发生了什么。</p><figure><img src="/assets/33-BIiKxLNb.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="训练大脑里的大模型-1" tabindex="-1"><a class="header-anchor" href="#训练大脑里的大模型-1"><span>训练大脑里的大模型</span></a></h2><p>我曾经给《AI 大模型项目落地实战》这门课写过一个宣传语。“大模型到底是什么新物种！一个 20 年老程序员，躬身入局 AI 时代，一年实战经验小记。”</p><p>对于工程师或超级个体来说，这门课可以帮助你完成从大模型知识到能力的跃迁，提高竞争力。</p><p>对于技术管理者来说，课程有大量丰富的架构，项目设计和经验教训总结，能帮你减少大模型项目实战中走弯路的概率。对于创业创新者来说，我们在多个行业的业务实践，已经取得了客户价值，对你的 AI 业务创新也很有参考价值。</p><p>很多人一说起大模型，想到的是“从 0 开始训练一个自己的大模型”，但我的经验表明，<strong>人脑子里的大模型才是真正的关键。</strong></p><p><strong>就像大模型微调的本质是调整大模型参数的数值，并不是更新具体的数据。</strong> 如果把大模型生成式比作一个“人”走路的话，参数更新就是在调整地图上的路径，目的是让这个“人”走的路“方向正确”，也就是调整你想让他输出的预期方向。</p><p>训练我们大脑里的大模型，就是要不断地将 AI 大模型和实际工作结合，用这些经验调教你的大脑，让它具备驾驭 AI 大模型的思维。我们需要的不只是更新知识，而是大模型开发的思维和方法。</p><p>希望你通过这些大模型应用开发案例的学习，能够尽快将 AI 结合到你自己的应用里，实现百倍的价值提升！</p><p>咱们这门课的案例，有教师的判作业系统，有营销文章 / 营销图片 / 营销视频这类 AI 营销系统的开发，还有电商行业微调达大模型，还有大模型评估专家的开发。你期待哪个项目？你手上在做什么项目？关于开发者的大模型之路，你还有什么疑问吗？</p><p>欢迎你在留言区和我交流，咱们下一讲，正式迈出第一步！</p></details>`,50)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};